  "data": {
    "count": 3,
    "results": [
      {
        "selector": "ChatMessageBubble",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatMessageBubble",
            "subComponentOf": "Chat",
            "displayName": "Chat Message Bubble",
            "isHiddenFromOverview": true,
            "description": "Styled content container for the chat \"bubble.\" Reads sender from parent ChatMessage context to auto-style the background. Use filled for standard messages and ghost when content needs alignment without a visible boundary. Supports name/metadata slots aligned with bubble padding, and multi-bubble grouping via the group prop for consecutive messages from the same sender.",
            "props": [
              {
                "name": "children",
                "type": "ReactNode",
                "description": "Bubble content: text, Markdown, or any ReactNode.",
                "required": true
              },
              {
                "name": "variant",
                "type": "'filled' | 'ghost'",
                "description": "Visual variant. 'filled' renders sender-colored background (default). 'ghost' renders transparent background but keeps padding for alignment.",
                "default": "'filled'"
              },
              {
                "name": "name",
                "type": "ReactNode",
                "description": "Sender name rendered above the bubble, aligned with bubble text padding. Use on the first bubble in a message. Non-rendering scalar values (null, undefined, booleans, and the empty string) omit the aligned wrapper; numeric 0 remains aligned. If the first content is raw (no bubble), use ChatMessage's `name` prop instead."
              },
              {
                "name": "metadata",
                "type": "ReactNode",
                "description": "Metadata content rendered below the bubble, aligned with bubble text padding. Use on the last bubble in a message. Non-rendering scalar values (null, undefined, booleans, and the empty string) omit the aligned wrapper; numeric 0 remains aligned. If the last content is raw (no bubble), use ChatMessage's `metadata` prop instead.",
                "slotElements": [
                  {
                    "__element": "Text",
                    "props": {
                      "type": "body"
                    },
                    "children": "Metadata"
                  }
                ]
              },
              {
                "name": "group",
                "type": "'first' | 'middle' | 'last'",
                "description": "Position within a multi-bubble group. Controls corner radius reduction on the sender side. Leave unset for standalone bubbles (full radius)."
              },
              {
                "name": "width",
                "type": "SizeValue",
                "description": "Width of the bubble (number = pixels, string = used as-is). When set, replaces the default max(80%, 280px) width cap. Combine with variant=\"ghost\" to let custom content (an artifact card, attachments) span the full message column."
              }
            ],
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      },
      {
        "selector": "ChatMessageList",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatMessageList",
            "subComponentOf": "Chat",
            "displayName": "Chat Message List",
            "isHiddenFromOverview": true,
            "description": "Presentational message container with density context and infinite scroll support. Provides role=\"log\" with aria-live=\"polite\" for accessibility. A flex spacer pushes messages to the bottom when the list isn't full; set align=\"top\" to start messages at the top instead.",
            "playground": {
              "defaults": {
                "children": [
                  {
                    "__element": "ChatMessage",
                    "props": {
                      "sender": "user"
                    },
                    "children": {
                      "__element": "ChatMessageBubble",
                      "children": "Can you summarize this report?"
                    }
                  },
                  {
                    "__element": "ChatMessage",
                    "props": {
                      "sender": "assistant"
                    },
                    "children": {
                      "__element": "ChatMessageBubble",
                      "children": "Sure. Revenue is up 12% and churn is flat quarter over quarter."
                    }
                  }
                ]
              },
              "wrapper": {
                "component": "Stack",
                "props": {
                  "width": 480
                }
              }
            },
            "props": [
              {
                "name": "children",
                "type": "ReactNode",
                "description": "Message elements: typically ChatMessage or ChatSystemMessage.",
                "required": true,
                "slotElements": [
                  {
                    "__element": "ChatMessage",
                    "props": {
                      "sender": "user"
                    },
                    "children": {
                      "__element": "ChatMessageBubble",
                      "children": "Message text"
                    }
                  }
                ]
              },
              {
                "name": "emptyState",
                "type": "ReactNode",
                "description": "Content shown when the list has no messages.",
                "slotElements": [
                  {
                    "__element": "EmptyState",
                    "props": {
                      "title": "No items",
                      "description": "Nothing to show."
                    }
                  }
                ]
              },
              {
                "name": "scrollToTopAction",
                "type": "() => Promise<void>",
                "description": "Async action fired when user scrolls to top. Use for loading older messages. Wrapped in useTransition: shows a spinner at the top while pending."
              },
              {
                "name": "density",
                "type": "'compact' | 'balanced' | 'spacious'",
                "description": "Visual density: flows to child messages via context.",
                "default": "'balanced'"
              },
              {
                "name": "gap",
                "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
                "description": "Gap between top-level message rows. Defaults to the selected density; override for LLM event streams or independent rows that need different spacing from density."
              },
              {
                "name": "align",
                "type": "'top' | 'bottom'",
                "description": "Vertical alignment when the list is shorter than its container. 'bottom' fills free space with a spacer so short conversations sit above the composer; 'top' omits the spacer so messages start at the top. Only affects a non-full list; overflowing lists scroll identically, preserving auto-scroll-to-bottom.",
                "default": "'bottom'"
              },
              {
                "name": "isStreaming",
                "type": "boolean",
                "description": "Whether an assistant message is actively streaming. Marks the log aria-busy so screen readers wait and announce the completed message once instead of re-announcing partial text on every token.",
                "default": "false"
              }
            ],
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      },
      {
        "selector": "ChatMessageMetadata",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatMessageMetadata",
            "subComponentOf": "Chat",
            "displayName": "Chat Message Metadata",
            "description": "Composable metadata row for chat messages. Renders timestamp, footer content, and delivery status in a single row. Direction reverses for user sender. Omits the row when both slots are omitted or non-rendering scalars and status is omitted.",
            "props": [
              {
                "name": "timestamp",
                "type": "ReactNode",
                "description": "Timestamp content: a string or Timestamp component.",
                "slotElements": [
                  {
                    "__element": "Text",
                    "props": {
                      "type": "body"
                    },
                    "children": "Just now"
                  }
                ]
              },
              {
                "name": "footer",
                "type": "ReactNode",
                "description": "Footer content: model info, reaction buttons, copy button.",
                "slotElements": [
                  {
                    "__element": "Text",
                    "props": {
                      "type": "body"
                    },
                    "children": "Footer content"
                  }
                ]
              },
              {
                "name": "status",
                "type": "'sending' | 'sent' | 'delivered' | 'read' | 'error'",
                "description": "Message delivery status. Shows icon + label."
              }
            ],
            "usage": {
              "description": "Place ChatMessageMetadata below a message or in the last ChatMessageBubble metadata slot to show a timestamp, footer content, and optional delivery status. Non-rendering scalar slots (booleans and empty strings) create no separator; numeric zero remains visible. Composite React content remains caller-owned.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Put metadata in the last bubble metadata slot when the message uses bubbles, so it follows the bubble content."
                },
                {
                  "guidance": true,
                  "description": "Pass timestamp and footer content independently; separators are omitted for non-rendering scalar slots. Composite React nodes are used as supplied."
                },
                {
                  "guidance": false,
                  "description": "Do not supply footer actions without their own accessible names and interaction behavior; the metadata row does not own those controls."
                },
                {
                  "guidance": false,
                  "description": "Do not put the same metadata on both a bubble and its enclosing message."
                }
              ],
              "anatomy": [
                {
                  "name": "Metadata row",
                  "required": true,
                  "description": "Sender-aware line containing the visible metadata items."
                },
                {
                  "name": "Timestamp",
                  "required": false,
                  "description": "Caller-supplied time content at the start of the logical sequence."
                },
                {
                  "name": "Footer",
                  "required": false,
                  "description": "Caller-supplied information or actions between time and status."
                },
                {
                  "name": "Status",
                  "required": false,
                  "description": "Localized delivery icon and text when a status is supplied."
                }
              ]
            },
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      }
    ]
  },
